 21	package com.pousada;
 22	
 23	import com.zaxxer.hikari.HikariConfig;
 24	import com.zaxxer.hikari.HikariDataSource;
 25	import org.slf4j.Logger;
 26	import org.slf4j.LoggerFactory;
 27	
 28	import java.sql.Connection;
 29	import java.sql.Statement;
 30	
 31	public class Database {
 32	    private static final Logger logger = LoggerFactory.getLogger(Database.class);
 33	    private static HikariDataSource dataSource;
 34	
 35	    public static void init() {
 36	        String dbUrl = System.getenv("DB_URL");
 37	        String dbUser = System.getenv("DB_USER");
 38	        String dbPassword = System.getenv("DB_PASSWORD");
 39	
 40	        if (dbUrl == null || dbUser == null || dbPassword == null) {
 41	            throw new IllegalStateException("DB_URL, DB_USER, and DB_PASSWORD environment variables must be set");
 42	        }
 43	
 44	        HikariConfig config = new HikariConfig();
 45	        config.setJdbcUrl(dbUrl);
 46	        config.setUsername(dbUser);
 47	        config.setPassword(dbPassword);
 48	        config.setMaximumPoolSize(10);
 49	        config.setMinimumIdle(2);
 50	
 51	        dataSource = new HikariDataSource(config);
 52	        createSchema();
 53	        logger.info("Database initialized");
 54	    }
 55	
 56	    private static void createSchema() {
 57	        try (Connection conn = dataSource.getConnection();
 58	             Statement stmt = conn.createStatement()) {
 59	
 60	            stmt.execute("""
 61	                    CREATE TABLE IF NOT EXISTS rooms (
 62	                        number INTEGER PRIMARY KEY,
 63	                        type VARCHAR(50) NOT NULL,
 64	                        capacity INTEGER NOT NULL,
 65	                        nightly_rate NUMERIC(10, 2) NOT NULL
 66	                    )
 67	                    """);
 68	
 69	            stmt.execute("""
 70	                    CREATE TABLE IF NOT EXISTS reservations (
 71	                        id SERIAL PRIMARY KEY,
 72	                        room_number INTEGER NOT NULL,
 73	                        guest_name VARCHAR(255) NOT NULL,
 74	                        guest_email VARCHAR(255) NOT NULL,
 75	                        guest_cpf VARCHAR(14) NOT NULL,
 76	                        check_in DATE NOT NULL,
 77	                        check_out DATE NOT NULL,
 78	                        guests INTEGER NOT NULL,
 79	                        rate_plan VARCHAR(50) NOT NULL,
 80	                        nights INTEGER NOT NULL,
 81	                        subtotal NUMERIC(10, 2) NOT NULL,
 82	                        discount NUMERIC(10, 2) NOT NULL,
 83	                        total NUMERIC(10, 2) NOT NULL,
 84	                        status VARCHAR(50) NOT NULL,
 85	                        amount_paid NUMERIC(10, 2) NOT NULL DEFAULT 0,
 86	                        refund NUMERIC(10, 2),
 87	                        FOREIGN KEY (room_number) REFERENCES rooms(number)
 88	                    )
 89	                    """);
 90	
 91	            stmt.execute("""
 92	                    CREATE TABLE IF NOT EXISTS messages (
 93	                        id SERIAL PRIMARY KEY,
 94	                        channel VARCHAR(50) NOT NULL,
 95	                        recipient_email VARCHAR(255) NOT NULL,
 96	                        subject VARCHAR(255) NOT NULL,
 97	                        body TEXT NOT NULL,
 98	                        created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP
 99	                    )
100	                    """);
101	
102	            insertRooms();
103	
104	            logger.info("Schema created successfully");
105	        } catch (Exception e) {
106	            logger.error("Failed to create schema", e);
107	            throw new RuntimeException(e);
108	        }
109	    }
110	
111	    private static void insertRooms() {
112	        try (Connection conn = dataSource.getConnection();
113	             Statement stmt = conn.createStatement()) {
114	
115	            // Check if rooms already exist
116	            var result = stmt.executeQuery("SELECT COUNT(*) as cnt FROM rooms");
117	            result.next();
118	            if (result.getInt("cnt") > 0) {
119	                return;
120	            }
121	
122	            stmt.execute("INSERT INTO rooms (number, type, capacity, nightly_rate) VALUES (101, 'STANDARD', 2, 249.90)");
123	            stmt.execute("INSERT INTO rooms (number, type, capacity, nightly_rate) VALUES (102, 'STANDARD', 2, 249.90)");
124	            stmt.execute("INSERT INTO rooms (number, type, capacity, nightly_rate) VALUES (201, 'DELUXE', 3, 389.90)");
125	            stmt.execute("INSERT INTO rooms (number, type, capacity, nightly_rate) VALUES (202, 'DELUXE', 3, 389.90)");
126	            stmt.execute("INSERT INTO rooms (number, type, capacity, nightly_rate) VALUES (301, 'SUITE', 4, 579.90)");
127	
128	            logger.info("Rooms inserted");
129	        } catch (Exception e) {
130	            logger.error("Failed to insert rooms", e);
131	            throw new RuntimeException(e);
132	        }
133	    }
134	
135	    public static HikariDataSource getDataSource() {
136	        return dataSource;
137	    }
138	
139	    public static Connection getConnection() throws Exception {
140	        return dataSource.getConnection();
141	    }
142	}
