171	    public static void setupRoutes(Javalin app) {
172	        app.get("/rooms", ctx -> {
173	            var rooms = RoomRepository.findAll();
174	            ctx.json(rooms.stream().map(r -> Map.of(
175	                "number", r.getNumber(),
176	                "type", r.getType(),
177	                "capacity", r.getCapacity(),
178	                "nightlyRate", r.getNightlyRate()
179	            )).toList());
180	        });
