182	        app.post("/reservations", ctx -> {
183	            try {
184	                JsonObject body = gson.fromJson(ctx.body(), JsonObject.class);
185	
186	                if (!body.has("roomNumber") || !body.has("guestName") || !body.has("guestEmail") ||
187	                    !body.has("guestCpf") || !body.has("checkIn") || !body.has("checkOut") ||
188	                    !body.has("guests") || !body.has("ratePlan")) {
189	                    throw new BadRequestResponse("Missing required fields");
190	                }
191	
192	                int roomNumber = body.get("roomNumber").getAsInt();
193	                String guestName = body.get("guestName").getAsString();
194	                String guestEmail = body.get("guestEmail").getAsString();
195	                String guestCpf = body.get("guestCpf").getAsString();
196	                String checkInStr = body.get("checkIn").getAsString();
197	                String checkOutStr = body.get("checkOut").getAsString();
198	                int guests = body.get("guests").getAsInt();
199	                String ratePlanStr = body.get("ratePlan").getAsString();
200	
201	                DateTimeFormatter formatter = DateTimeFormatter.ISO_LOCAL_DATE;
202	                LocalDate checkIn = LocalDate.parse(checkInStr, formatter);
203	                LocalDate checkOut = LocalDate.parse(checkOutStr, formatter);
204	
205	                if (checkOut.compareTo(checkIn) <= 0) {
206	                    throw new BadRequestResponse("Checkout must be after checkin");
207	                }
208	
209	                if (guests < 1) {
210	                    throw new BadRequestResponse("Guests must be at least 1");
211	                }
212	
213	                RatePlan ratePlan = RatePlan.valueOf(ratePlanStr);
214	
215	                Reservation reservation = ReservationService.createReservation(
216	                    roomNumber, guestName, guestEmail, guestCpf,
217	                    checkIn, checkOut, guests, ratePlan);
218	
219	                ctx.status(201);
220	                ctx.json(buildReservationResponse(reservation));
221	            } catch (BadRequestResponse e) {
222	                throw e;
223	            } catch (IllegalArgumentException e) {
224	                handleReservationError(ctx, e);
225	            } catch (Exception e) {
226	                ctx.status(400);
227	                ctx.json(Map.of("error", "INVALID_REQUEST", "message", e.getMessage()));
228	            }
229	        });
230	
231	        app.get("/reservations/{id}", ctx -> {
232	            try {
233	                int id = Integer.parseInt(ctx.pathParam("id"));
234	                var reservation = ReservationRepository.findById(id);
235	                if (reservation.isEmpty()) {
236	                    ctx.status(404);
237	                    ctx.json(Map.of("error", "RESERVATION_NOT_FOUND", "message", "Reservation not found"));
238	                    return;
239	                }
240	                ctx.json(buildReservationResponse(reservation.get()));
241	            } catch (Exception e) {
242	                ctx.status(400);
243	                ctx.json(Map.of("error", "INVALID_REQUEST", "message", e.getMessage()));
244	            }
245	        });
246	
247	        app.post("/reservations/{id}/confirmation", ctx -> {
248	            try {
249	                int id = Integer.parseInt(ctx.pathParam("id"));
250	                JsonObject body = gson.fromJson(ctx.body(), JsonObject.class);
251	
252	                if (!body.has("amountPaid")) {
253	                    throw new BadRequestResponse("Missing amountPaid");
254	                }
255	
256	                BigDecimal amountPaid = body.get("amountPaid").getAsBigDecimal();
257	                Reservation reservation = ReservationService.confirmReservation(id, amountPaid);
258	                ctx.json(buildReservationResponse(reservation));
259	            } catch (IllegalArgumentException e) {
260	                handleReservationError(ctx, e);
261	            } catch (Exception e) {
262	                ctx.status(400);
263	                ctx.json(Map.of("error", "INVALID_REQUEST", "message", e.getMessage()));
264	            }
265	        });
266	
267	        app.post("/reservations/{id}/cancellation", ctx -> {
268	            try {
269	                int id = Integer.parseInt(ctx.pathParam("id"));
270	                Reservation reservation = ReservationService.cancelReservation(id);
271	                ctx.json(buildReservationResponse(reservation));
272	            } catch (IllegalArgumentException e) {
273	                handleReservationError(ctx, e);
274	            } catch (Exception e) {
275	                ctx.status(400);
276	                ctx.json(Map.of("error", "INVALID_REQUEST", "message", e.getMessage()));
277	            }
278	        });
279	
280	        app.post("/reservations/{id}/check-in", ctx -> {
281	            try {
282	                int id = Integer.parseInt(ctx.pathParam("id"));
283	                Reservation reservation = ReservationService.checkIn(id);
284	                ctx.json(buildReservationResponse(reservation));
285	            } catch (IllegalArgumentException e) {
286	                handleReservationError(ctx, e);
287	            } catch (Exception e) {
288	                ctx.status(400);
289	                ctx.json(Map.of("error", "INVALID_REQUEST", "message", e.getMessage()));
290	            }
291	        });
292	
293	        app.post("/reservations/{id}/check-out", ctx -> {
294	            try {
295	                int id = Integer.parseInt(ctx.pathParam("id"));
296	                Reservation reservation = ReservationService.checkOut(id);
297	                String receipt = DocumentService.generateReceipt(reservation);
298	
299	                var room = RoomRepository.findByNumber(reservation.getRoomNumber()).get();
300	                Map<String, Object> response = new LinkedHashMap<>();
301	                response.put("title", "Comprovante de reserva");
302	                response.put("reservationId", reservation.getId());
303	                response.put("guestName", reservation.getGuestName());
304	                response.put("guestCpf", reservation.getGuestCpf());
305	                response.put("roomNumber", reservation.getRoomNumber());
306	                response.put("roomType", room.getType());
307	                response.put("checkIn", reservation.getCheckIn().toString());
308	                response.put("checkOut", reservation.getCheckOut().toString());
309	                response.put("nights", reservation.getNights());
310	                response.put("subtotal", reservation.getSubtotal());
311	                response.put("discount", reservation.getDiscount());
312	                response.put("total", reservation.getTotal());
313	
314	                ctx.json(response);
315	            } catch (IllegalArgumentException e) {
316	                handleReservationError(ctx, e);
317	            } catch (Exception e) {
318	                ctx.status(400);
319	                ctx.json(Map.of("error", "INVALID_REQUEST", "message", e.getMessage()));
320	            }
321	        });
322	
323	        app.get("/reservations/{id}/document", ctx -> {
324	            try {
325	                int id = Integer.parseInt(ctx.pathParam("id"));
326	                var reservationOpt = ReservationRepository.findById(id);
327	                if (reservationOpt.isEmpty()) {
328	                    ctx.status(404);
329	                    ctx.json(Map.of("error", "RESERVATION_NOT_FOUND", "message", "Reservation not found"));
330	                    return;
331	                }
332	                Reservation reservation = reservationOpt.get();
333	
334	                var room = RoomRepository.findByNumber(reservation.getRoomNumber()).get();
335	                Map<String, Object> response = new LinkedHashMap<>();
336	                response.put("title", "Comprovante de reserva");
337	                response.put("reservationId", reservation.getId());
338	                response.put("guestName", reservation.getGuestName());
339	                response.put("guestCpf", reservation.getGuestCpf());
340	                response.put("roomNumber", reservation.getRoomNumber());
341	                response.put("roomType", room.getType());
342	                response.put("checkIn", reservation.getCheckIn().toString());
343	                response.put("checkOut", reservation.getCheckOut().toString());
344	                response.put("nights", reservation.getNights());
345	                response.put("subtotal", reservation.getSubtotal());
346	                response.put("discount", reservation.getDiscount());
347	                response.put("total", reservation.getTotal());
348	
349	                ctx.json(response);
350	            } catch (Exception e) {
351	                ctx.status(400);
352	                ctx.json(Map.of("error", "INVALID_REQUEST", "message", e.getMessage()));
353	            }
354	        });
355	
356	        app.get("/messages", ctx -> {
357	            var messages = MessageRepository.findAll();
358	            ctx.json(messages.stream().map(m -> Map.of(
359	                "id", m.getId(),
360	                "channel", m.getChannel(),
361	                "to", m.getTo(),
362	                "subject", m.getSubject(),
363	                "body", m.getBody()
364	            )).toList());
365	        });
366	
367	        app.get("/reports/occupancy", ctx -> {
368	            try {
369	                String dateStr = ctx.queryParam("date");
370	                if (dateStr == null) {
371	                    throw new BadRequestResponse("Missing date parameter");
372	                }
373	                LocalDate date = LocalDate.parse(dateStr, DateTimeFormatter.ISO_LOCAL_DATE);
374	                String report = ReportService.generateOccupancyReport(date);
375	                ctx.contentType("text/csv; charset=utf-8");
376	                ctx.result(report);
377	            } catch (Exception e) {
378	                ctx.status(400);
379	                ctx.json(Map.of("error", "INVALID_REQUEST", "message", e.getMessage()));
380	            }
381	        });
382	
383	        app.get("/reports/revenue", ctx -> {
384	            try {
385	                String monthStr = ctx.queryParam("month");
386	                if (monthStr == null) {
387	                    throw new BadRequestResponse("Missing month parameter");
388	                }
389	                YearMonth month = YearMonth.parse(monthStr, DateTimeFormatter.ofPattern("yyyy-MM"));
390	                String report = ReportService.generateRevenueReport(month);
391	                ctx.contentType("text/csv; charset=utf-8");
392	                ctx.result(report);
393	            } catch (Exception e) {
394	                ctx.status(400);
395	                ctx.json(Map.of("error", "INVALID_REQUEST", "message", e.getMessage()));
396	            }
397	        });
398	
399	        app.get("/reports/tourism-tax", ctx -> {
400	            try {
401	                String monthStr = ctx.queryParam("month");
402	                if (monthStr == null) {
403	                    throw new BadRequestResponse("Missing month parameter");
404	                }
405	                YearMonth month = YearMonth.parse(monthStr, DateTimeFormatter.ofPattern("yyyy-MM"));
406	                String report = ReportService.generateTourismTaxReport(month);
407	                ctx.contentType("text/csv; charset=utf-8");
408	                ctx.result(report);
409	            } catch (Exception e) {
410	                ctx.status(400);
411	                ctx.json(Map.of("error", "INVALID_REQUEST", "message", e.getMessage()));
412	            }
413	        });
414	
415	        app.get("/reports/rate-plans", ctx -> {
416	            try {
417	                String monthStr = ctx.queryParam("month");
418	                if (monthStr == null) {
419	                    throw new BadRequestResponse("Missing month parameter");
420	                }
421	                YearMonth month = YearMonth.parse(monthStr, DateTimeFormatter.ofPattern("yyyy-MM"));
422	                String report = ReportService.generateRatePlansReport(month);
423	                ctx.contentType("text/csv; charset=utf-8");
424	                ctx.result(report);
425	            } catch (Exception e) {
426	                ctx.status(400);
427	                ctx.json(Map.of("error", "INVALID_REQUEST", "message", e.getMessage()));
428	            }
429	        });
430	    }
431	
432	    private static void handleReservationError(io.javalin.http.Context ctx, IllegalArgumentException e) {
433	        String message = e.getMessage();
434	        if ("ROOM_NOT_FOUND".equals(message)) {
435	            ctx.status(404);
436	            ctx.json(Map.of("error", "ROOM_NOT_FOUND", "message", "Room not found"));
437	        } else if ("RESERVATION_NOT_FOUND".equals(message)) {
438	            ctx.status(404);
439	            ctx.json(Map.of("error", "RESERVATION_NOT_FOUND", "message", "Reservation not found"));
440	        } else if ("ROOM_UNAVAILABLE".equals(message)) {
441	            ctx.status(409);
442	            ctx.json(Map.of("error", "ROOM_UNAVAILABLE", "message", "Room is not available for these dates"));
443	        } else if ("CAPACITY_EXCEEDED".equals(message)) {
444	            ctx.status(422);
445	            ctx.json(Map.of("error", "CAPACITY_EXCEEDED", "message", "Too many guests for this room"));
446	        } else if ("OPERATION_NOT_ALLOWED".equals(message)) {
447	            ctx.status(409);
448	            ctx.json(Map.of("error", "OPERATION_NOT_ALLOWED", "message", "This operation is not allowed for the current reservation status"));
449	        } else {
450	            ctx.status(400);
451	            ctx.json(Map.of("error", "INVALID_REQUEST", "message", message));
452	        }
453	    }
454	
455	    private static Map<String, Object> buildReservationResponse(Reservation r) {
456	        Map<String, Object> map = new LinkedHashMap<>();
457	        map.put("id", r.getId());
458	        map.put("roomNumber", r.getRoomNumber());
459	        map.put("guestName", r.getGuestName());
460	        map.put("guestEmail", r.getGuestEmail());
461	        map.put("guestCpf", r.getGuestCpf());
462	        map.put("checkIn", r.getCheckIn().toString());
463	        map.put("checkOut", r.getCheckOut().toString());
464	        map.put("guests", r.getGuests());
465	        map.put("ratePlan", r.getRatePlan().toString());
466	        map.put("nights", r.getNights());
467	        map.put("subtotal", r.getSubtotal());
468	        map.put("discount", r.getDiscount());
469	        map.put("total", r.getTotal());
470	        map.put("status", r.getStatus().toString());
471	        map.put("amountPaid", r.getAmountPaid());
472	        map.put("refund", r.getRefund());
473	        return map;
474	    }
475	}

