435	            ctx.status(404);
436	            ctx.json(Map.of("error", "ROOM_NOT_FOUND", "message", "Room not found"));
437	        } else if ("RESERVATION_NOT_FOUND".equals(message)) {
438	            ctx.status(404);
439	            ctx.json(Map.of("error", "RESERVATION_NOT_FOUND", "message", "Reservation not found"));
440	        } else if ("ROOM_UNAVAILABLE".equals(message)) {
441	            ctx.status(409);
442	            ctx.json(Map.of("error", "ROOM_UNAVAILABLE", "message", "Room is not available for these dates"));
443	        } else if ("CAPACITY_EXCEEDED".equals(message)) {
444	            ctx.status(422);
445	            ctx.json(Map.of("error", "CAPACITY_EXCEEDED", "message", "Too many guests for this room"));
446	        } else if ("OPERATION_NOT_ALLOWED".equals(message)) {
447	            ctx.status(409);
448	            ctx.json(Map.of("error", "OPERATION_NOT_ALLOWED", "message", "This operation is not allowed for the current reservation status"));
449	        } else {
450	            ctx.status(400);
451	            ctx.json(Map.of("error", "INVALID_REQUEST", "message", message));
452	        }
453	    }
