  9	public class DocumentService {
 10	    private static final DateTimeFormatter DATE_FORMATTER = DateTimeFormatter.ofPattern("dd/MM/yyyy");
 11	    private static final DecimalFormat MONEY_FORMATTER = new DecimalFormat("0.00");
 12	
 13	    static {
 14	        MONEY_FORMATTER.setGroupingUsed(true);
 15	        MONEY_FORMATTER.setGroupingSize(3);
 16	    }
 17	
 18	    public static String generateReceipt(Reservation reservation) {
 19	        var room = RoomRepository.findByNumber(reservation.getRoomNumber()).get();
 20	
 21	        StringBuilder sb = new StringBuilder();
 22	        sb.append(String.format("Comprovante de reserva nº %d\n", reservation.getId()));
 23	        sb.append(String.format("Hóspede: %s (CPF %s)\n", reservation.getGuestName(), formatCpf(reservation.getGuestCpf())));
 24	        sb.append(String.format("Quarto: %d (%s)\n", reservation.getRoomNumber(), room.getType()));
 25	
 26	        String checkInFormatted = reservation.getCheckIn().format(DATE_FORMATTER);
 27	        String checkOutFormatted = reservation.getCheckOut().format(DATE_FORMATTER);
 28	        String nightsText = reservation.getNights() == 1 ? "1 diária" : reservation.getNights() + " diárias";
 29	        sb.append(String.format("Entrada: %s | Saída: %s | %s\n", checkInFormatted, checkOutFormatted, nightsText));
 30	
 31	        sb.append(String.format("Diárias: R$ %s\n", formatMoney(reservation.getSubtotal())));
 32	
 33	        if (reservation.getDiscount().compareTo(java.math.BigDecimal.ZERO) > 0) {
 34	            sb.append(String.format("Desconto: R$ %s\n", formatMoney(reservation.getDiscount())));
 35	        }
 36	
 37	        sb.append(String.format("Total: R$ %s", formatMoney(reservation.getTotal())));
 38	
 39	        return sb.toString();
 40	    }
 41	
 42	    private static String formatCpf(String cpf) {
 43	        if (cpf == null || cpf.length() != 11) {
 44	            return cpf;
 45	        }
 46	        return String.format("%s.%s.%s-%s",
 47	            cpf.substring(0, 3),
 48	            cpf.substring(3, 6),
 49	            cpf.substring(6, 9),
 50	            cpf.substring(9, 11));
 51	    }
 52	
 53	    private static String formatMoney(java.math.BigDecimal value) {
 54	        return String.format("%.2f", value);
 55	    }
 56	}
