187	
188	        List<Reservation> allReservations = ReservationRepository.findByMonthStart(year, month);
189	        List<Reservation> paidReservations = allReservations.stream()
190	            .filter(r -> r.getAmountPaid().compareTo(BigDecimal.ZERO) > 0)
191	            .collect(Collectors.toList());
192	
