194	        csv.append(String.format("Pousada Maré Alta,revenue,%s\n", yearMonth));
195	        csv.append("reservation,room,check_in,check_out,status,amount\n");
196	
197	        BigDecimal total = BigDecimal.ZERO;
198	        for (Reservation r : paidReservations) {
199	            BigDecimal amount = r.getAmountPaid().subtract(r.getRefund() == null ? BigDecimal.ZERO : r.getRefund());
200	            csv.append(String.format("%d,%d,%s,%s,%s,%.2f\n",
201	                r.getId(),
202	                r.getRoomNumber(),
203	                formatDateISO(r.getCheckIn()),
204	                formatDateISO(r.getCheckOut()),
205	                r.getStatus(),
206	                amount));
