 84	package com.pousada.service;
 85	
 86	import com.pousada.model.RatePlan;
 87	
 88	import java.math.BigDecimal;
 89	import java.math.RoundingMode;
 90	import java.time.LocalDate;
 91	
 92	public class PricingCalculator {
 93	    private static final BigDecimal HIGH_SEASON_MULTIPLIER = BigDecimal.valueOf(1.20);
 94	    private static final BigDecimal DISCOUNT_RATE = BigDecimal.valueOf(0.15);
 95	
 96	    public static BigDecimal calculateNightlyPrice(BigDecimal baseRate, LocalDate date) {
 97	        if (isHighSeason(date)) {
 98	            BigDecimal highSeasonPrice = baseRate.multiply(HIGH_SEASON_MULTIPLIER);
 99	            return roundHalfToEven(highSeasonPrice);
100	        }
101	        return baseRate;
102	    }
103	
104	    public static BigDecimal calculateSubtotal(BigDecimal nightlyPrice, int nights) {
105	        BigDecimal subtotal = nightlyPrice.multiply(BigDecimal.valueOf(nights));
106	        return roundHalfToEven(subtotal);
107	    }
108	
109	    public static BigDecimal calculateDiscount(BigDecimal subtotal, RatePlan ratePlan) {
110	        if (ratePlan == RatePlan.NON_REFUNDABLE) {
111	            BigDecimal discount = subtotal.multiply(DISCOUNT_RATE);
112	            return roundHalfToEven(discount);
113	        }
114	        return BigDecimal.ZERO;
115	    }
116	
117	    public static BigDecimal calculateTotal(BigDecimal subtotal, BigDecimal discount) {
118	        BigDecimal total = subtotal.subtract(discount);
119	        return roundHalfToEven(total);
120	    }
121	
122	    public static BigDecimal roundHalfToEven(BigDecimal value) {
123	        return value.setScale(2, RoundingMode.HALF_EVEN);
124	    }
125	
126	    private static boolean isHighSeason(LocalDate date) {
127	        int month = date.getMonthValue();
128	        int day = date.getDayOfMonth();
129	
130	        // December 15 - February 28/29
131	        if (month == 12 && day >= 15) return true;
132	        if (month == 1) return true;
133	        if (month == 2) return true;
134	
135	        // All of July
136	        if (month == 7) return true;
137	
138	        return false;
139	    }
140	
141	    public static int calculateNights(LocalDate checkIn, LocalDate checkOut) {
142	        return (int) java.time.temporal.ChronoUnit.DAYS.between(checkIn, checkOut);
143	    }
144	}
