380	        var reservationOpt = ReservationRepository.findById(reservationId);
381	        if (reservationOpt.isEmpty()) {
382	            throw new IllegalArgumentException("RESERVATION_NOT_FOUND");
383	        }
384	
385	        Reservation reservation = reservationOpt.get();
386	        if (reservation.getStatus() != ReservationStatus.CONFIRMED) {
387	            throw new IllegalArgumentException("OPERATION_NOT_ALLOWED");
388	        }
389	
390	        reservation.setStatus(ReservationStatus.CHECKED_IN);
391	        ReservationRepository.update(reservation);
392	
393	        return reservation;
394	    }
395	
396	    public static Reservation checkOut(int reservationId) {
397	        var reservationOpt = ReservationRepository.findById(reservationId);
398	        if (reservationOpt.isEmpty()) {
399	            throw new IllegalArgumentException("RESERVATION_NOT_FOUND");
400	        }
401	
402	        Reservation reservation = reservationOpt.get();
403	        if (reservation.getStatus() != ReservationStatus.CHECKED_IN) {
404	            throw new IllegalArgumentException("OPERATION_NOT_ALLOWED");
405	        }
406	
407	        reservation.setStatus(ReservationStatus.CHECKED_OUT);
408	        ReservationRepository.update(reservation);
409	
410	        return reservation;
411	    }
412	
413	    public static Reservation cancelReservation(int reservationId) {
414	        var reservationOpt = ReservationRepository.findById(reservationId);
415	        if (reservationOpt.isEmpty()) {
416	            throw new IllegalArgumentException("RESERVATION_NOT_FOUND");
417	        }
418	
419	        Reservation reservation = reservationOpt.get();
420	        if (reservation.getStatus() != ReservationStatus.PENDING &&
421	            reservation.getStatus() != ReservationStatus.CONFIRMED) {
422	            throw new IllegalArgumentException("OPERATION_NOT_ALLOWED");
423	        }
424	
425	        // Calculate refund before changing status
426	        ReservationStatus oldStatus = reservation.getStatus();
427	        if (oldStatus == ReservationStatus.CONFIRMED &&
428	            reservation.getRatePlan() == RatePlan.STANDARD) {
429	            reservation.setRefund(reservation.getAmountPaid());
430	        } else {
431	            reservation.setRefund(BigDecimal.ZERO);
432	        }
433	
434	        reservation.setStatus(ReservationStatus.CANCELLED);
435	        ReservationRepository.update(reservation);
436	
437	        return reservation;
438	    }
